function EulerChar(h11, h21, h31, h22):
    diamond <- case table from the four free numbers
               (corners=1; (1,1),(3,3)=h11; (1,3),(3,1)=h31;
                (2,2)=h22; (2,1),(1,2),(2,3),(3,2)=h21; else 0)
    chi <- 0
    for p in 0..4:
        for q in 0..4:
            chi <- chi + (-1)^(p+q) * diamond[p][q]
    return chi      # equals 4 + 2 h11 + 2 h31 + h22 - 4 h21

