function MirrorSwap(h11, h21, h31, h22):
    return (h31, h21, h11, h22)          # exchange h11 <-> h31

function IsInvolution(X):
    return MirrorSwap(MirrorSwap(X)) == X

function EulerInvariant(X):
    return EulerChar(X) == EulerChar(MirrorSwap(X))

